const fs = require('fs');
const file = '/data/notes-gantsevich.json';
const body = $json.body ?? {};
if (!body.title) throw new Error('title is required');
let notes = [];
try { notes = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (error) { if (error.code !== 'ENOENT') throw error; }
const id = String(body.id ?? Date.now());
if (notes.some(note => note.id === id)) throw new Error('note with this id already exists');
const note = { id, title: body.title, text: body.text ?? '', author: 'Gantsevich', createdAt: new Date().toISOString() };
notes.push(note);
fs.writeFileSync(file, JSON.stringify(notes, null, 2));
return [{ json: { ok: true, operation: 'created', storage: file, note } }];

const fs = require('fs');
const file = '/data/notes-gantsevich.json';
let notes = [];
