return [{ json: { ok: true, storage: file, count: notes.length, notes } }];

const fs = require('fs');
const file = '/data/notes-gantsevich.json';
const id = String($json.query?.id ?? '');
let notes = [];
try { notes = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (error) { if (error.code !== 'ENOENT') throw error; }
const note = notes.find(item => item.id === id);
return [{ json: note ? { ok: true, note } : { ok: false, error: 'Note not found', id } }];

const fs = require('fs');
const file = '/data/notes-gantsevich.json';
const id = String($json.query?.id ?? '');
const body = $json.body ?? {};
if (!id) throw new Error('id query parameter is required');
if (!body.title) throw new Error('title is required');
let notes = [];
try { notes = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (error) { if (error.code !== 'ENOENT') throw error; }
const index = notes.findIndex(note => note.id === id);
if (index < 0) return [{ json: { ok: false, error: 'Note not found', id } }];
const note = { ...notes[index], title: body.title, text: body.text ?? '', updatedAt: new Date().toISOString() };
notes[index] = note;
fs.writeFileSync(file, JSON.stringify(notes, null, 2));
return [{ json: { ok: true, operation: 'updated', storage: file, note } }];

const fs = require('fs');
const file = '/data/notes-gantsevich.json';
const id = String($json.query?.id ?? '');
let notes = [];
try { notes = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (error) { if (error.code !== 'ENOENT') throw error; }
const before = notes.length;
notes = notes.filter(note => note.id !== id);
const deleted = notes.length < before;
if (deleted) fs.writeFileSync(file, JSON.stringify(notes, null, 2));
return [{ json: deleted ? { ok: true, operation: 'deleted', id, storage: file } : { ok: false, error: 'Note not found', id } }];
